func Scan(text string) []Finding {
    // 1. standalone terms (paedophile, rapist…) — refused with or without a name,
    //    because requiring a name would let "he is a …" through on a pronoun
    // 2. drive from the allegation:
    for _, occ := range allegationOccurrences(lower) {
        if name, ok := nameNear(text, occ, proximityWords); ok {
            out = append(out, Finding{Kind: "named-allegation", Match: name, Term: occ.term})
        }
    }
}

// a token capitalised ONLY by sentence position is not a name — but position
// alone is not evidence, so it is used together with a sentenceOpeners set
if opensSentence(text, lo+loc[0]) && sentenceOpeners[strings.ToLower(tok)] { continue }

func TestOpinionAboutNamedThingsIsALLOWED(t *testing.T) {
    for _, s := range []string{
        "Christopher Nolan is overrated and Tenet proves it.",
        "The Beatles are the most boring band ever canonised.",
        ...
    } { if f := Scan(s); f != nil { t.Errorf("REFUSED an opinion, which kills the product: %q", s) } }
}

round, rerr := store.GetRound(ctx, pool, body.RoundID)
if round.SiteID != siteID { 404 }   // answer exactly what PublishRound would have
if findings := namecheck.ScanAll(round.PositionText, round.DefenceText,
        string(round.Counter), string(round.Verdict)); len(findings) > 0 {
    logPublishRefusal(body.RoundID, findings)
    422 "…appears to make a factual claim about a named person or business. Your round is unaffected."
}

func logPublishRefusal(roundID string, findings []namecheck.Finding) {
    kinds := make([]string, 0, len(findings))
    for _, f := range findings { kinds = append(kinds, f.Kind+":"+f.Term) } // NOT f.Match
    log.Printf("gauntlet/publish: REFUSED round_id=%s findings=%d signals=%v", roundID, len(findings), kinds)
}
